"use client";
import { useEffect,useState } from "react";import Link from "next/link";import Image from "next/image";import { Plus,Trash2,Pencil } from "lucide-react";import { api } from "@/lib/api-client";import { formatNaira } from "@/lib/mock-data";import type { ApiProduct } from "@/lib/api-types";
export default function VendorProductsPage(){const[products,setProducts]=useState<ApiProduct[]|null>(null);async function load(){const{products}=await api.get<{products:ApiProduct[]}>("/api/products/me/list");setProducts(products);}useEffect(()=>{void load();},[]);async function handleDelete(id:string){if(!confirm("Delete this product? This can't be undone."))return;await api.delete(`/api/products/${id}`);void load();}return <div className="shell py-8"><div className="flex items-center justify-between"><h1 className="text-xl font-bold text-graphite-900">My products</h1><Link href="/vendor/dashboard/products/new" className="flex items-center gap-1.5 rounded-card bg-ember-600 px-4 py-2 text-sm font-semibold text-white hover:bg-ember-700"><Plus className="h-4 w-4"/>New product</Link></div>{products===null?<p className="mt-6 text-sm text-graphite-600">Loading…</p>:products.length===0?<div className="mt-6 rounded-card border border-dashed border-graphite-200 p-10 text-center text-sm text-graphite-600">You haven't listed any products yet.</div>:<div className="mt-6 flex flex-col gap-2">{products.map(p=><div key={p.id} className="flex items-center gap-3 rounded-card border border-graphite-200 p-3"><div className="relative h-14 w-14 shrink-0 overflow-hidden rounded-[6px] bg-cloud-100">{p.images[0]&&<Image src={p.images[0].url} alt={p.name} fill sizes="56px" className="object-cover"/>}</div><div className="min-w-0 flex-1"><p className="truncate text-sm font-medium text-graphite-900">{p.name}</p><p className="font-mono text-[11px] text-graphite-500">Product ID: {p.publicProductId??p.id}</p><p className="text-xs text-graphite-600">{formatNaira(Number(p.price))} · {p.stock} in stock · {p.estimatedDeliveryDays??7} day delivery · <span className={p.status==="ACTIVE"?"text-verified-600":p.status==="SUSPENDED"?"text-ember-600":"text-graphite-400"}>{p.status.toLowerCase()}</span></p></div><Link href={`/vendor/dashboard/products/${p.id}/edit`} className="grid h-8 w-8 shrink-0 place-items-center rounded-card text-graphite-600 hover:bg-cloud-100" aria-label="Edit"><Pencil className="h-4 w-4"/></Link><button onClick={()=>handleDelete(p.id)} className="grid h-8 w-8 shrink-0 place-items-center rounded-card text-graphite-600 hover:bg-ember-100 hover:text-ember-700" aria-label="Delete"><Trash2 className="h-4 w-4"/></button></div>)}</div>}</div>}
